(4697072, 677899, 41675, '<td valign="top">:-) Good bear shot. Hopefully you used a big zoom lens from far away! Cute title</td>', ':-) Good bear shot. Hopefully you used a big zoom lens from far away! Cute title', '2008-05-12 12:49:23.000000', NULL, 1),
(4697073, 678009, 29474, '<td valign="top">Interesting picture. Nice to see a different technique being used. Makes it stand out</td>', 'Interesting picture. Nice to see a different technique being used. Makes it stand out', '2008-05-12 12:50:25.000000', NULL, 1),
(4697075, 677784, 88791, '<td valign="top">Simply stunning!</td>', 'Simply stunning!', '2008-05-12 12:50:53.000000', NULL, 1),
