(4697079, 677983, 29474, '<td valign="top">I like the posterised effect of the background,</td>', 'I like the posterised effect of the background,', '2008-05-12 12:54:06.000000', NULL, 1),
(4697082, 677508, 29474, '<td valign="top">Is this a new game? About to become an Olympic sport? Pity that he isn''t looking at the brolly.</td>', 'Is this a new game? About to become an Olympic sport? Pity that he isn''t looking at the brolly.', '2008-05-12 12:55:09.000000', NULL, 1),
