(4697085, 677840, 41675, '<td valign="top">Good title to fit your image. I do wish the entire rider was in the photo, but that''s just me. Good dof, lighting and colors.</td>', 'Good title to fit your image. I do wish the entire rider was in the photo, but that''s just me. Good dof, lighting and colors.', '2008-05-12 12:56:27.000000', NULL, 1),
(4697086, 677963, 29474, '<td valign="top">Very subtle. Very gentle. Nice contrast with the background. Great lighting on the petals.</td>', 'Very subtle. Very gentle. Nice contrast with the background. Great lighting on the petals.', '2008-05-12 12:57:09.000000', NULL, 1),
(4697090, 677824, 41675, '<td valign="top">Your title makes me laugh. I get the sens you couldn''t quite come up with anything. Irregardless, nice floral macro and composition. For me, had the lighting been a bit more dramatic I would have scored it higher.</td>', 'Your title makes me laugh. I get the sens you couldn''t quite come up with anything. Irregardless, nice floral macro and composition. For me, had the lighting been a bit more dramatic I would have scored it higher.', '2008-05-12 12:57:34.000000', NULL, 1),
(4697091, 677947, 29474, '<td valign="top">What a crazy eclectic mess.</td>', 'What a crazy eclectic mess.', '2008-05-12 12:57:58.000000', NULL, 1),
(4697093, 677916, 41675, '<td valign="top">Good title for your image. I like the color contrast,composition and water droplets. Best of luck in the challenge.</td>', 'Good title for your image. I like the color contrast,composition and water droplets. Best of luck in the challenge.', '2008-05-12 12:58:31.000000', NULL, 1),
(4697097, 677898, 29474, '<td valign="top">Prefer the blurry commuter title. Fantastic image. maybe a bit too much space on the right.</td>', 'Prefer the blurry commuter title. Fantastic image. maybe a bit too much space on the right.', '2008-05-12 12:59:16.000000', NULL, 1),
(4697099, 677642, 29474, '<td valign="top">Simple. Good contrast with background.</td>', 'Simple. Good contrast with background.', '2008-05-12 12:59:43.000000', NULL, 1),
(4697101, 677625, 29474, '<td valign="top">The building looks familiar. I''m sure that I''ve seen it in a challenge before.</td>', 'The building looks familiar. I''m sure that I''ve seen it in a challenge before.', '2008-05-12 13:00:20.000000', NULL, 1),
