INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4697106, 677958, 29474, '<td valign="top">Nice composition. Good to see the eye against the black head. Very difficult to do and you pulled it off.</td>', 'Nice composition. Good to see the eye against the black head. Very difficult to do and you pulled it off.', '2008-05-12 13:03:07.000000', NULL, 1),
(4697135, 677937, 73235, '<td valign="top">good job separating the player from the background. good, strong natural tones and colors (not oversaturated)</td>', 'good job separating the player from the background. good, strong natural tones and colors (not oversaturated)', '2008-05-12 13:14:06.000000', NULL, 1),
(4697140, 677211, 73235, '<td valign="top">would have loved to see more of the reflection in the water. so the model could be seen 3 times: original, shadow and reflection. &lt;and less sky&gt;</td>', 'would have loved to see more of the reflection in the water. so the model could be seen 3 times: original, shadow and reflection. <and less sky>', '2008-05-12 13:16:30.000000', NULL, 1),
(4697143, 677517, 73235, '<td valign="top">cool idea, good choice of DOF to highlight your ahmmm... subjects</td>', 'cool idea, good choice of DOF to highlight your ahmmm... subjects', '2008-05-12 13:18:52.000000', NULL, 1),
(4697145, 677989, 73235, '<td valign="top">I like the contrast in the sky. The foregound is yoo dark for my taste. the fish-eye appearance is therefore not as visible/obvious</td>', 'I like the contrast in the sky. The foregound is yoo dark for my taste. the fish-eye appearance is therefore not as visible/obvious', '2008-05-12 13:20:58.000000', NULL, 1),
(4697148, 676366, 73235, '<td valign="top">good partial desat. I like the eye contact with the dog.</td>', 'good partial desat. I like the eye contact with the dog.', '2008-05-12 13:22:11.000000', NULL, 1),
(4697149, 677657, 91998, '<td valign="top">Great action shot and great title. I checked the Jerseys to make sure the names were right ;)</td>', 'Great action shot and great title. I checked the Jerseys to make sure the names were right ;)', '2008-05-12 13:22:28.000000', NULL, 1),
(4697154, 678006, 73235, '<td valign="top">I like your composition and how you guide the viewer across the bridge and then right to the ocean.</td>', 'I like your composition and how you guide the viewer across the bridge and then right to the ocean.', '2008-05-12 13:26:05.000000', NULL, 1),
(4697160, 678012, 73235, '<td valign="top">I like the arrangement. It looks like they''re opening towards the light.</td>', 'I like the arrangement. It looks like they''re opening towards the light.', '2008-05-12 13:26:50.000000', NULL, 1),
(4697162, 676781, 91998, '<td valign="top">Ha ha, love the title. Is this jam for real or did you make the label yourself?</td>', 'Ha ha, love the title. Is this jam for real or did you make the label yourself?', '2008-05-12 13:27:34.000000', NULL, 1),
(4697167, 676366, 91998, '<td valign="top">Great use of PP and a great action pic. Nice one.</td>', 'Great use of PP and a great action pic. Nice one.', '2008-05-12 13:28:45.000000', NULL, 1),
(4697170, 677943, 73235, '<td valign="top">great job capturing this moment. I wish the focus would be a bit more in the face than the hair.</td>', 'great job capturing this moment. I wish the focus would be a bit more in the face than the hair.', '2008-05-12 13:30:15.000000', NULL, 1),
(4697183, 677963, 73235, '<td valign="top">I like the soft focus and the "reach" of the flower to the light.</td>', 'I like the soft focus and the "reach" of the flower to the light.', '2008-05-12 13:37:14.000000', NULL, 1),
(4697184, 677122, 73235, '<td valign="top">good composition and bokeh. nice warm tones</td>', 'good composition and bokeh. nice warm tones', '2008-05-12 13:39:09.000000', NULL, 1),
(4697190, 677545, 73235, '<td valign="top">good job freezing the motion. initially I did not like the centered approach, but on second thought the water splashes left and right convinced me otherwise.</td>', 'good job freezing the motion. initially I did not like the centered approach, but on second thought the water splashes left and right convinced me otherwise.', '2008-05-12 13:41:12.000000', NULL, 1),
(4697198, 677956, 73235, '<td valign="top">I see your thoughts in the composition of your picture. I''m not too fond of the big areas to the top left and top middle. They are basically empty and do not add details or have any othe function. May be alower angle (height of the child''s eyes) and framing the picture really around the kid and waterfall only could make it stronger.</td>', 'I see your thoughts in the composition of your picture. I''m not too fond of the big areas to the top left and top middle. They are basically empty and do not add details or have any othe function. May be alower angle (height of the child''s eyes) and framing the picture really around the kid and waterfall only could make it stronger.', '2008-05-12 13:47:09.000000', NULL, 1),
(4697200, 677908, 73235, '<td valign="top">great way to show off the bird''s character. well exposed and lots of details</td>', 'great way to show off the bird''s character. well exposed and lots of details', '2008-05-12 13:48:06.000000', NULL, 1),
(4697203, 677974, 73235, '<td valign="top">yes it is and it''s well executed also</td>', 'yes it is and it''s well executed also', '2008-05-12 13:48:58.000000', NULL, 1),
(4697205, 676828, 73235, '<td valign="top">well exposed with good detail, good DOF</td>', 'well exposed with good detail, good DOF', '2008-05-12 13:50:05.000000', NULL, 1),
(4697207, 677927, 26001, '<td valign="top">This is funny and clever. the pov makes the shot for me. the BG looks a little blotchy though.</td>', 'This is funny and clever. the pov makes the shot for me. the BG looks a little blotchy though.', '2008-05-12 13:50:12.000000', NULL, 1),
(4697211, 677777, 26001, '<td valign="top">very nice use of desat, which cleverly establishes the relationship between subjects. the diagonal composition feels dynamic and reinforce the bike/cycle movement. nice job spotting the potential of this shot.</td>', 'very nice use of desat, which cleverly establishes the relationship between subjects. the diagonal composition feels dynamic and reinforce the bike/cycle movement. nice job spotting the potential of this shot.', '2008-05-12 13:52:55.000000', NULL, 1),
(4697213, 677856, 73235, '<td valign="top">beautiful b/w picture. I like the contrast between the white hose, the blach background and the dark door.</td>', 'beautiful b/w picture. I like the contrast between the white hose, the blach background and the dark door.', '2008-05-12 13:53:42.000000', NULL, 1),
(4697215, 677974, 91295, '<td valign="top">Do I vote high or low...fantastic example of you title subject...but it is exactly that..so what to do, what to do?  Guess I have to give it a 9, simply because the tips of the two petals in the foreground are OOF....maybe one more F-Stop to get them, but fade off into the nice, cliche'' bokeh.</td>', 'Do I vote high or low...fantastic example of you title subject...but it is exactly that..so what to do, what to do?  Guess I have to give it a 9, simply because the tips of the two petals in the foreground are OOF....maybe one more F-Stop to get them, but fade off into the nice, cliche'' bokeh.', '2008-05-12 13:53:48.000000', NULL, 1),
(4697218, 677974, 26001, '<td valign="top">indeed!!! title is very clever. the photo looks a little too bright for my taste.</td>', 'indeed!!! title is very clever. the photo looks a little too bright for my taste.', '2008-05-12 13:54:04.000000', NULL, 1),
(4697221, 677228, 73235, '<td valign="top">it might be my monitor, but the blue appears overly saturated. great focus and isolation from the background.</td>', 'it might be my monitor, but the blue appears overly saturated. great focus and isolation from the background.', '2008-05-12 13:55:03.000000', NULL, 1),
(4697225, 677847, 26001, '<td valign="top">beautifully serene and colorful. btw seems like you have a hot-pixel in top-right quadrant (~2 o''clock).</td>', 'beautifully serene and colorful. btw seems like you have a hot-pixel in top-right quadrant (~2 o''clock).', '2008-05-12 13:56:13.000000', NULL, 1),
(4697226, 677845, 73235, '<td valign="top">one of my favs. focus, color, light, composition, everything is right.10</td>', 'one of my favs. focus, color, light, composition, everything is right.10', '2008-05-12 13:56:16.000000', NULL, 1),
(4697231, 677941, 73235, '<td valign="top">very good detail</td>', 'very good detail', '2008-05-12 13:57:52.000000', NULL, 1),
(4697235, 677625, 26001, '<td valign="top">beautifully composed. good job putting the sphere at top-left thirds. blues in the shot are gorgeous. also the cubes(straight lines) of the building works very well with the sphere.</td>', 'beautifully composed. good job putting the sphere at top-left thirds. blues in the shot are gorgeous. also the cubes(straight lines) of the building works very well with the sphere.', '2008-05-12 14:01:33.000000', NULL, 1),
(4697237, 677722, 26001, '<td valign="top">absolutely stunning. this should be on the front page.</td>', 'absolutely stunning. this should be on the front page.', '2008-05-12 14:01:59.000000', NULL, 1),
(4697240, 676397, 73235, '<td valign="top">your focus is where it should be. the cat''s face seems a little dark. there is barely details to see. Your composition lets you down very much in this pic. the very very busy foreground lets the viewer not focus on what you want to show. These branches/bushes also work against isolating the cat from the busy background.</td>', 'your focus is where it should be. the cat''s face seems a little dark. there is barely details to see. Your composition lets you down very much in this pic. the very very busy foreground lets the viewer not focus on what you want to show. These branches/bushes also work against isolating the cat from the busy background.', '2008-05-12 14:03:08.000000', NULL, 1),
(4697241, 677840, 26001, '<td valign="top">very nice sports shot (minus the cropped hand, of course). shadows are a little too dark btw.</td>', 'very nice sports shot (minus the cropped hand, of course). shadows are a little too dark btw.', '2008-05-12 14:04:01.000000', NULL, 1),
(4697242, 677579, 73235, '<td valign="top">cool "action macro"!</td>', 'cool "action macro"!', '2008-05-12 14:04:16.000000', NULL, 1),
(4697244, 677552, 26001, '<td valign="top">fantastic composition and brilliant exposure of such a difficult subject (shiny-reflecting) in white background. should see you on the podium :)</td>', 'fantastic composition and brilliant exposure of such a difficult subject (shiny-reflecting) in white background. should see you on the podium :)', '2008-05-12 14:05:05.000000', NULL, 1),
(4697246, 677954, 73235, '<td valign="top">great job while riding (I hope as a passenger). I like your bright processing</td>', 'great job while riding (I hope as a passenger). I like your bright processing', '2008-05-12 14:05:40.000000', NULL, 1),
(4697247, 677852, 26001, '<td valign="top">excellent. one minor nit-pick is, the subject needs just a little more room at the top of the frame.</td>', 'excellent. one minor nit-pick is, the subject needs just a little more room at the top of the frame.', '2008-05-12 14:06:03.000000', NULL, 1),
(4697250, 677931, 26001, '<td valign="top">excellent pov, composition, exposure, and bw conversion. that big white blob (table?) is distracting though. i am sure you would clone that out, if it was allowed by editing rules. overall i like it.</td>', 'excellent pov, composition, exposure, and bw conversion. that big white blob (table?) is distracting though. i am sure you would clone that out, if it was allowed by editing rules. overall i like it.', '2008-05-12 14:07:35.000000', NULL, 1),
(4697252, 677174, 26001, '<td valign="top">good job with the shot, especially composition and exposure, as well as on the title. should be in top-10, at least.</td>', 'good job with the shot, especially composition and exposure, as well as on the title. should be in top-10, at least.', '2008-05-12 14:08:56.000000', NULL, 1),
(4697254, 677785, 26001, '<td valign="top">one of the better uses of HDR, for sure. although because of the PP, viewer don''t get the "back-lit" feel from the shot.</td>', 'one of the better uses of HDR, for sure. although because of the PP, viewer don''t get the "back-lit" feel from the shot.', '2008-05-12 14:10:13.000000', NULL, 1),
(4697310, 677192, 61818, '<td valign="top">Hahaha great title.</td>', 'Hahaha great title.', '2008-05-12 14:28:54.000000', NULL, 1),
(4697313, 677930, 76598, '<td valign="top">The focus appears just a tad off.</td>', 'The focus appears just a tad off.', '2008-05-12 14:29:38.000000', NULL, 1),
(4697328, 677853, 76598, '<td valign="top">Where''s the "W"  :)</td>', 'Where''s the "W"  :)', '2008-05-12 14:32:20.000000', NULL, 1),
(4697329, 677833, 90947, '<td valign="top">Absolutely gorgeous Damsel and an extravagant fan indeed.  Perfect match with the challenge. I love it.  <br/> <br/>a couple of nearly trivial observations, but as observations is what this site is all about... The model sees to have a bit a green cast above her eyes and along the right side of her neck.  I might have brought her up and to the left in the frame, but maybe not... <br/> <br/>All in all, I love the shot.</td>', 'Absolutely gorgeous Damsel and an extravagant fan indeed.  Perfect match with the challenge. I love it.   a couple of nearly trivial observations, but as observations is what this site is all about... The model sees to have a bit a green cast above her eyes and along the right side of her neck.  I might have brought her up and to the left in the frame, but maybe not...  All in all, I love the shot.', '2008-05-12 14:32:21.000000', NULL, 1),
(4697331, 677786, 68887, '<td valign="top">too much hdr for me.. at least for this challenge</td>', 'too much hdr for me.. at least for this challenge', '2008-05-12 14:32:30.000000', NULL, 1),
(4697335, 677785, 68887, '<td valign="top">too oversaturated.. maybe due to hdr..</td>', 'too oversaturated.. maybe due to hdr..', '2008-05-12 14:33:27.000000', NULL, 1),
(4697360, 677683, 90947, '<td valign="top">Great match on the challenge.  Very pretty ballerina.  <br/> <br/>The shot looks a little out of focus.  I think it would have been good to have moved the model a little to her left to avoid the edge of the curtain.  Perhaps her tutu(?) could have been pushed down so it didn''t fill the space defined by her left arm.  The curtail itself is very nice.  From what I can see of the pattern, it leaves me with a Russian Ballet environment.<br/> <br/>Very nice shot.</td>', 'Great match on the challenge.  Very pretty ballerina.   The shot looks a little out of focus.  I think it would have been good to have moved the model a little to her left to avoid the edge of the curtain.  Perhaps her tutu(?) could have been pushed down so it didn''t fill the space defined by her left arm.  The curtail itself is very nice.  From what I can see of the pattern, it leaves me with a Russian Ballet environment. Very nice shot.', '2008-05-12 14:42:50.000000', NULL, 1),
(4697362, 677174, 92383, '<td valign="top">Beautiful.  This could be a poster.</td>', 'Beautiful.  This could be a poster.', '2008-05-12 14:43:26.000000', NULL, 1),
(4697364, 677612, 92383, '<td valign="top">I like the Color of the tractor. 9</td>', 'I like the Color of the tractor. 9', '2008-05-12 14:44:20.000000', NULL, 1),
(4697369, 677533, 92383, '<td valign="top">Perfect title.  Looks almost fake. 9</td>', 'Perfect title.  Looks almost fake. 9', '2008-05-12 14:46:31.000000', NULL, 1),
(4697370, 677968, 36382, '<td valign="top">It feels like you are actually there.</td>', 'It feels like you are actually there.', '2008-05-12 14:47:19.000000', NULL, 1),
(4697371, 677907, 92383, '<td valign="top">I think this is wonderful.  I guess I would like to see the tips of the horns but it is hard to be critical. 9</td>', 'I think this is wonderful.  I guess I would like to see the tips of the horns but it is hard to be critical. 9', '2008-05-12 14:48:04.000000', NULL, 1),
(4697374, 677981, 36382, '<td valign="top">This is funny and well done.  I like the lighting.  It looks like there is an extra foot and hand in there, too.</td>', 'This is funny and well done.  I like the lighting.  It looks like there is an extra foot and hand in there, too.', '2008-05-12 14:49:12.000000', NULL, 1),
(4697376, 677730, 73235, '<td valign="top">great composition, details and all the other technicals. What I really love here is the expression of the elephant''s face: relaxed, comfortable. title and picture are really in sync.</td>', 'great composition, details and all the other technicals. What I really love here is the expression of the elephant''s face: relaxed, comfortable. title and picture are really in sync.', '2008-05-12 14:49:51.000000', NULL, 1),
(4697379, 677185, 90947, '<td valign="top">Very cute little ballet student and the title certainly matches the challenge.  Did you intentionally make it look like a faded slide?</td>', 'Very cute little ballet student and the title certainly matches the challenge.  Did you intentionally make it look like a faded slide?', '2008-05-12 14:50:43.000000', NULL, 1),
(4697381, 677703, 36382, '<td valign="top">This is a good take on the famous Michelangelo painting.  He is languishing just like Adam.  The only thing I''m not sure about is the twigs.  I think you needed something there, but I''m not sure these did the job.  IMO of course.</td>', 'This is a good take on the famous Michelangelo painting.  He is languishing just like Adam.  The only thing I''m not sure about is the twigs.  I think you needed something there, but I''m not sure these did the job.  IMO of course.', '2008-05-12 14:52:15.000000', NULL, 1),
(4697383, 677170, 90947, '<td valign="top">I love it... It fits the challenge perfectly and certainly shows considerable math difficulties.  I am curious about the two forms of "<b>7</b>", but I am curious about many things.</td>', 'I love it... It fits the challenge perfectly and certainly shows considerable math difficulties.  I am curious about the two forms of "7", but I am curious about many things.', '2008-05-12 14:52:55.000000', NULL, 1),
(4697387, 677508, 90947, '<td valign="top">Wonderful action shot.  One can see the effort in the child''s throw.  All of the subject but the very tip of the umbrella is in great focus and the background is well out of focus. The sharpness of the umbrella make me wonder if this is one photo.  In any event, very nice job.</td>', 'Wonderful action shot.  One can see the effort in the child''s throw.  All of the subject but the very tip of the umbrella is in great focus and the background is well out of focus. The sharpness of the umbrella make me wonder if this is one photo.  In any event, very nice job.', '2008-05-12 14:56:22.000000', NULL, 1),
(4697393, 677914, 90947, '<td valign="top">Great shot.  The look on the boy''s face and the saturated colors makes this look like it could be on the box of "mac and cheese".  The knuckles on the hand got a little out of focus, but not to disctract from the look on the face.</td>', 'Great shot.  The look on the boy''s face and the saturated colors makes this look like it could be on the box of "mac and cheese".  The knuckles on the hand got a little out of focus, but not to disctract from the look on the face.', '2008-05-12 14:59:26.000000', NULL, 1),
(4697395, 677717, 92383, '<td valign="top">Nice and cold.  Duotone Blue?  I like it.</td>', 'Nice and cold.  Duotone Blue?  I like it.', '2008-05-12 15:00:57.000000', NULL, 1),
(4697396, 677052, 73235, '<td valign="top">This picture has great potential. Right now it looks flat, unsharp not really focused on the tiger. I don''t know whether you like this, but in less than 5 minutes with just basic editing and a little different cropping it could look like this: [thumb]678169[/thumb]<br/>Again, I don''t know whether you like what I did or not. But it shows exactly what I mean.</td>', 'This picture has great potential. Right now it looks flat, unsharp not really focused on the tiger. I don''t know whether you like this, but in less than 5 minutes with just basic editing and a little different cropping it could look like this: [thumb]678169[/thumb]Again, I don''t know whether you like what I did or not. But it shows exactly what I mean.', '2008-05-12 15:01:52.000000', NULL, 1),
(4697399, 677581, 92383, '<td valign="top">Hope everyone isn''t DNMCing you.  I see what you were doing.  Great entry</td>', 'Hope everyone isn''t DNMCing you.  I see what you were doing.  Great entry', '2008-05-12 15:02:51.000000', NULL, 1),
(4697401, 677657, 52713, '<td valign="top">Go Astros!</td>', 'Go Astros!', '2008-05-12 15:06:25.000000', NULL, 1),
(4697462, 676421, 55956, '<td valign="top">well done!</td>', 'well done!', '2008-05-12 15:35:38.000000', NULL, 1),
(4697467, 677974, 55956, '<td valign="top">eheheh never title was more right :)</td>', 'eheheh never title was more right :)', '2008-05-12 15:37:08.000000', NULL, 1),
