INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4698257, 677981, 65234, '<td valign="top">I''m a little concerned about the number and placement of hands =:-O</td>', 'I''m a little concerned about the number and placement of hands =:-O', '2008-05-12 22:45:56.000000', NULL, 1),
(4698258, 677963, 91496, '<td valign="top">Nice photo, love the background.  The background is ethereal rather then the flower and the title counts more than usual on this challege.</td>', 'Nice photo, love the background.  The background is ethereal rather then the flower and the title counts more than usual on this challege.', '2008-05-12 22:46:04.000000', NULL, 1),
(4698259, 677876, 65234, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2008-05-12 22:46:09.000000', NULL, 1),
(4698263, 677947, 65234, '<td valign="top">Doncha'' hate it when that happens?  Now someone''s going to have to recombobulate all that stuff!  Best title so far, and enjoyably eclectic scene.</td>', 'Doncha'' hate it when that happens?  Now someone''s going to have to recombobulate all that stuff!  Best title so far, and enjoyably eclectic scene.', '2008-05-12 22:48:13.000000', NULL, 1),
(4698264, 677913, 91496, '<td valign="top">Eerie photo.  Clouds seem to be mismatched to the sunny lighting and the large white area on the right is a bit distracting.</td>', 'Eerie photo.  Clouds seem to be mismatched to the sunny lighting and the large white area on the right is a bit distracting.', '2008-05-12 22:48:21.000000', NULL, 1),
(4698265, 677975, 61651, '<td valign="top">I feel like I''m playing a game of hide and go seek - this is mesmerizing.  It puts me in the moment - an odd moment, but it puts me there.  :)</td>', 'I feel like I''m playing a game of hide and go seek - this is mesmerizing.  It puts me in the moment - an odd moment, but it puts me there.  :)', '2008-05-12 22:48:25.000000', NULL, 1),
(4698267, 677712, 88136, '<td valign="top">seems a bit out of focus, cool idea though</td>', 'seems a bit out of focus, cool idea though', '2008-05-12 22:49:22.000000', NULL, 1),
(4698269, 677130, 88136, '<td valign="top">cant quite find where this is focused, trippy idea though</td>', 'cant quite find where this is focused, trippy idea though', '2008-05-12 22:49:48.000000', NULL, 1),
(4698270, 677228, 65234, '<td valign="top">I''m going to have to go Bluebird-stalking; first there was a western one in the FS, and now this lovely eastern one.  I am feeling peer pressure ... or I''m just flat out jealous of people who are getting gorgeous shots of Bluebirds ;-)</td>', 'I''m going to have to go Bluebird-stalking; first there was a western one in the FS, and now this lovely eastern one.  I am feeling peer pressure ... or I''m just flat out jealous of people who are getting gorgeous shots of Bluebirds ;-)', '2008-05-12 22:50:12.000000', NULL, 1),
(4698272, 677655, 65234, '<td valign="top">Oh, with little baby duckies and everything.  Very pretty scene.</td>', 'Oh, with little baby duckies and everything.  Very pretty scene.', '2008-05-12 22:50:49.000000', NULL, 1),
(4698273, 677947, 91496, '<td valign="top">Like the photo, not so sure of the title.</td>', 'Like the photo, not so sure of the title.', '2008-05-12 22:51:04.000000', NULL, 1),
(4698274, 677892, 65234, '<td valign="top">Very emotive.</td>', 'Very emotive.', '2008-05-12 22:52:09.000000', NULL, 1),
(4698275, 678012, 88136, '<td valign="top">cool idea, strange lighting on the upper flowers, seems a bit washed out near the bottom leaves and flower</td>', 'cool idea, strange lighting on the upper flowers, seems a bit washed out near the bottom leaves and flower', '2008-05-12 22:52:16.000000', NULL, 1),
(4698278, 677633, 88136, '<td valign="top">strange background. very cool detail on the flower</td>', 'strange background. very cool detail on the flower', '2008-05-12 22:52:37.000000', NULL, 1),
(4698280, 678011, 41675, '<td valign="top">Aside from your title seeming grammatically...off (which I don''t hold against the way I score), I really like the lighting in your image and the focus of the bird along with the reflection. Nicely done.</td>', 'Aside from your title seeming grammatically...off (which I don''t hold against the way I score), I really like the lighting in your image and the focus of the bird along with the reflection. Nicely done.', '2008-05-12 22:54:53.000000', NULL, 1),
(4698282, 677974, 90947, '<td valign="top">Very interesting shot.  I love the colors, very smooth.  Regarding matching the challenge.  Is DPChallenge a word?  Hum... I am not sure.  <br/> <br/>You might have tried to keep the defocused portions of the picture to either the front or the back or, if both, further from the sharp water drop.  Clearly, the water drop is important to be in focus, so I believe I might have brought closer to the foreground.</td>', 'Very interesting shot.  I love the colors, very smooth.  Regarding matching the challenge.  Is DPChallenge a word?  Hum... I am not sure.   You might have tried to keep the defocused portions of the picture to either the front or the back or, if both, further from the sharp water drop.  Clearly, the water drop is important to be in focus, so I believe I might have brought closer to the foreground.', '2008-05-12 22:55:41.000000', NULL, 1),
(4698283, 677958, 41675, '<td valign="top">I like the off-centered composition. For me, had the lighting been a bit different (brighter or more dramatic somehow) I would have scored it higher.</td>', 'I like the off-centered composition. For me, had the lighting been a bit different (brighter or more dramatic somehow) I would have scored it higher.', '2008-05-12 22:55:42.000000', NULL, 1),
(4698284, 677988, 65234, '<td valign="top">Could be a dream or a nightmare, depending on my mood.  I like the ambiguity.</td>', 'Could be a dream or a nightmare, depending on my mood.  I like the ambiguity.', '2008-05-12 22:55:57.000000', NULL, 1),
(4698288, 677885, 91496, '<td valign="top">Nice splash.  The usual "one bite from cholocalte bar" is cliche but really looks good.  This bite pattern is not a photogenic.  Of course maybe you got hungry.  Did you try white milk, as maybe there would be more contrast.</td>', 'Nice splash.  The usual "one bite from cholocalte bar" is cliche but really looks good.  This bite pattern is not a photogenic.  Of course maybe you got hungry.  Did you try white milk, as maybe there would be more contrast.', '2008-05-12 22:57:36.000000', NULL, 1),
(4698293, 677786, 41675, '<td valign="top">This is just me, but I''m not a fan of this type of post-processing, sorry. I do like the angle and the three houses however.</td>', 'This is just me, but I''m not a fan of this type of post-processing, sorry. I do like the angle and the three houses however.', '2008-05-12 22:59:59.000000', NULL, 1),
(4698297, 677482, 91496, '<td valign="top">Nice shot.  A polarizing filter can help with the glare that often happens in car hoods.</td>', 'Nice shot.  A polarizing filter can help with the glare that often happens in car hoods.', '2008-05-12 23:00:53.000000', NULL, 1),
