(4701426, 677228, 35998, '<td valign="top">Wow, it took my breath away.  Stunning color and composition!</td>', 'Wow, it took my breath away.  Stunning color and composition!', '2008-05-14 09:58:00.000000', NULL, 1),
(4701448, 677702, 35998, '<td valign="top">Great capture... Black and White format fits this so well...</td>', 'Great capture... Black and White format fits this so well...', '2008-05-14 10:06:05.000000', NULL, 1),
(4701451, 677169, 35998, '<td valign="top">Wish we saw a bit more sky... to balance the composition of the photo.  Otherwise, it''s quite nice.</td>', 'Wish we saw a bit more sky... to balance the composition of the photo.  Otherwise, it''s quite nice.', '2008-05-14 10:07:20.000000', NULL, 1),
(4701456, 677533, 35998, '<td valign="top">Wow.  It''s the first word that came to mind.</td>', 'Wow.  It''s the first word that came to mind.', '2008-05-14 10:08:57.000000', NULL, 1),
