(4701466, 677622, 35998, '<td valign="top">ooh!  I wish the whole plant was in focus, but I like it!</td>', 'ooh!  I wish the whole plant was in focus, but I like it!', '2008-05-14 10:11:17.000000', NULL, 1),
(4701608, 677670, 41675, '<td valign="top">I''m a fan of battlefields and the split rail fences - so I automatically like your image. Good saturation and I like the sunlight filtering through the clouds. Nice countryscape.</td>', 'I''m a fan of battlefields and the split rail fences - so I automatically like your image. Good saturation and I like the sunlight filtering through the clouds. Nice countryscape.', '2008-05-14 10:41:48.000000', NULL, 1),
(4701628, 677192, 72929, '<td valign="top">clever title</td>', 'clever title', '2008-05-14 10:45:03.000000', NULL, 1),
(4701645, 677864, 41675, '<td valign="top">My eyes are drawn to three separate elements of your photo: The window with the reflection, the clock on the right and then the winged horse. For me, the three items don''t seem to go together, but I like the color of the building.</td>', 'My eyes are drawn to three separate elements of your photo: The window with the reflection, the clock on the right and then the winged horse. For me, the three items don''t seem to go together, but I like the color of the building.', '2008-05-14 10:49:44.000000', NULL, 1),
(4701656, 677986, 91805, '<td valign="top">I would like this photo better if it were sharper.</td>', 'I would like this photo better if it were sharper.', '2008-05-14 10:53:57.000000', NULL, 1),
(4701677, 677852, 41675, '<td valign="top">Good hang time! :-) The title works for me and fits the challenge description too. I wish the background itself wasn''t so barren looking or maybe a bit of sky to give it more height, but overall, I like it.</td>', 'Good hang time! :-) The title works for me and fits the challenge description too. I wish the background itself wasn''t so barren looking or maybe a bit of sky to give it more height, but overall, I like it.', '2008-05-14 11:01:36.000000', NULL, 1),
(4701684, 677816, 41675, '<td valign="top">For me, your subject seems slightly out of focus and I find the object in the lower right distracting. I do like the expression you captured and the contrast of the green foliage in the background to his blue shirt.</td>', 'For me, your subject seems slightly out of focus and I find the object in the lower right distracting. I do like the expression you captured and the contrast of the green foliage in the background to his blue shirt.', '2008-05-14 11:03:36.000000', NULL, 1),
(4701805, 677908, 92383, '<td valign="top">Excellent Border! j/k - the bird is perfect from my perspective. 10</td>', 'Excellent Border! j/k - the bird is perfect from my perspective. 10', '2008-05-14 11:41:37.000000', NULL, 1),
(4701811, 678001, 92383, '<td valign="top">Awesome perspective.  See this is the big difference between good and great - those freaking colors.  Awesome. 10 (A kickin'' lens doesn''t hurt either!)</td>', 'Awesome perspective.  See this is the big difference between good and great - those freaking colors.  Awesome. 10 (A kickin'' lens doesn''t hurt either!)', '2008-05-14 11:43:36.000000', NULL, 1),
(4701813, 677554, 92383, '<td valign="top">Looks Jageresque. Bet everyone wants to know the circumstances of the shot. 10</td>', 'Looks Jageresque. Bet everyone wants to know the circumstances of the shot. 10', '2008-05-14 11:43:48.000000', NULL, 1),
(4701816, 677856, 92383, '<td valign="top">This horse reminds me of a heroin chic model. 10</td>', 'This horse reminds me of a heroin chic model. 10', '2008-05-14 11:44:16.000000', NULL, 1),
(4701818, 677886, 92383, '<td valign="top">Framing is really nice.  This would be an awesome watercolor.  For me that doesn''t take from the photograph.  The scene you have captured and flavored in post is inspirational. 10</td>', 'Framing is really nice.  This would be an awesome watercolor.  For me that doesn''t take from the photograph.  The scene you have captured and flavored in post is inspirational. 10', '2008-05-14 11:44:29.000000', NULL, 1),
(4701819, 677122, 92383, '<td valign="top">I think this is beautiful.  I hope everyone else does too.  I think I have better taste than ability.  I would have liked to have created this.  Hope your proud of it.  10</td>', 'I think this is beautiful.  I hope everyone else does too.  I think I have better taste than ability.  I would have liked to have created this.  Hope your proud of it.  10', '2008-05-14 11:44:44.000000', NULL, 1),
(4701972, 677655, 84124, '<td valign="top">A hair too soft for my liking, but a good shot regardless.</td>', 'A hair too soft for my liking, but a good shot regardless.', '2008-05-14 13:06:57.000000', NULL, 1),
(4702013, 677975, 84124, '<td valign="top">Absolutely wonderful!  So takes me back to endless hours waiting in the high grass for friends to show up for after school baseball.  View and perspective are delicious, the title is a bit weak, but that''s a minor nitpick.  7.</td>', 'Absolutely wonderful!  So takes me back to endless hours waiting in the high grass for friends to show up for after school baseball.  View and perspective are delicious, the title is a bit weak, but that''s a minor nitpick.  7.', '2008-05-14 13:27:44.000000', NULL, 1),
(4702022, 677943, 84124, '<td valign="top">One of my favorites so far.  Doubt this will score high with the DPC crowd for a couple of reasons, but this is such an intimate "real" photo.  Kudos.  Definite 7.</td>', 'One of my favorites so far.  Doubt this will score high with the DPC crowd for a couple of reasons, but this is such an intimate "real" photo.  Kudos.  Definite 7.', '2008-05-14 13:30:04.000000', NULL, 1),
(4702024, 677657, 84124, '<td valign="top">Great action shot!</td>', 'Great action shot!', '2008-05-14 13:30:30.000000', NULL, 1),
(4702026, 677703, 84124, '<td valign="top">The expression on her face is absolutely priceless!  I''m predicting top 20, great shot.</td>', 'The expression on her face is absolutely priceless!  I''m predicting top 20, great shot.', '2008-05-14 13:31:31.000000', NULL, 1),
(4702030, 677817, 84124, '<td valign="top">Wow!  Fantastic capture!</td>', 'Wow!  Fantastic capture!', '2008-05-14 13:33:21.000000', NULL, 1),
(4702033, 677886, 84124, '<td valign="top">Great photo, but weak title, not sure I see the "odd" part of the painting.</td>', 'Great photo, but weak title, not sure I see the "odd" part of the painting.', '2008-05-14 13:34:41.000000', NULL, 1);
