(4705193, 677919, 41675, '<td valign="top">I''ve looked at your image three times before voting. Overall I like it. The colors of the flowers against the black background and the reflections. I think my issue is the business of the upper left vs. the simplicity of the lower right. My eyes keep darting back to the glass, when I like the bud better.</td>', 'I''ve looked at your image three times before voting. Overall I like it. The colors of the flowers against the black background and the reflections. I think my issue is the business of the upper left vs. the simplicity of the lower right. My eyes keep darting back to the glass, when I like the bud better.', '2008-05-15 20:03:04.000000', NULL, 1),
(4705196, 677646, 41675, '<td valign="top">Title fits the challenge. I like the lighting of your image and the colors. It looks peaceful (wish I was there). Good composition as well. Best of luck in the challenge.</td>', 'Title fits the challenge. I like the lighting of your image and the colors. It looks peaceful (wish I was there). Good composition as well. Best of luck in the challenge.', '2008-05-15 20:04:00.000000', NULL, 1),
(4705198, 677185, 41675, '<td valign="top">Your title fits the challenge well. Seems a bit grainy, but that could have been your intention, and the color seems a bit on the yellowish side. I do like her her pose and expression though.</td>', 'Your title fits the challenge well. Seems a bit grainy, but that could have been your intention, and the color seems a bit on the yellowish side. I do like her her pose and expression though.', '2008-05-15 20:05:22.000000', NULL, 1),
(4705202, 677103, 41675, '<td valign="top">Great sunset colors! depending on the driver, I''m not sure how risky they are though ;-) Looks like fun. Nice image overall.</td>', 'Great sunset colors! depending on the driver, I''m not sure how risky they are though ;-) Looks like fun. Nice image overall.', '2008-05-15 20:06:45.000000', NULL, 1),
(4705204, 677169, 41675, '<td valign="top">Nice cityscape. Good morning light and clouds in the distance. too bad the water wasn''t a bit more still for the reflections. This would be a good tourism photo brochure...makes me want to check out Omaha. title is okay :-)</td>', 'Nice cityscape. Good morning light and clouds in the distance. too bad the water wasn''t a bit more still for the reflections. This would be a good tourism photo brochure...makes me want to check out Omaha. title is okay :-)', '2008-05-15 20:07:54.000000', NULL, 1),
(4705209, 677554, 41675, '<td valign="top">Hah! ha ha! wow! What a great capture. Terrific lighting and look as those teeth. Dang! Can''t see anything wrong with this one. One of my favorites and a definite 10. Good luck!</td>', 'Hah! ha ha! wow! What a great capture. Terrific lighting and look as those teeth. Dang! Can''t see anything wrong with this one. One of my favorites and a definite 10. Good luck!', '2008-05-15 20:08:55.000000', NULL, 1),
(4705213, 677868, 41675, '<td valign="top">Your title leaves me wondering two things: 1) is this really a queen and; 2) her rain starts by eating? :-) Good insect macro. I like the colors and textures. I''m not so sure I''d get that close to a bee myself though. You''re braver than I would be. (no pun intended). Lol.</td>', 'Your title leaves me wondering two things: 1) is this really a queen and; 2) her rain starts by eating? :-) Good insect macro. I like the colors and textures. I''m not so sure I''d get that close to a bee myself though. You''re braver than I would be. (no pun intended). Lol.', '2008-05-15 20:10:26.000000', NULL, 1),
(4705215, 677052, 41675, '<td valign="top">For me, your image seems a bit overexposed. A bit more contrast or saturation with sharper focus and I would have scored it better. Good title for your photo though.</td>', 'For me, your image seems a bit overexposed. A bit more contrast or saturation with sharper focus and I would have scored it better. Good title for your photo though.', '2008-05-15 20:11:23.000000', NULL, 1),
(4705217, 677853, 41675, '<td valign="top">Cheating and stretching the title a bit...and very yellow indeed. I like the blue of the sky to offset those yellow flowers.</td>', 'Cheating and stretching the title a bit...and very yellow indeed. I like the blue of the sky to offset those yellow flowers.', '2008-05-15 20:12:21.000000', NULL, 1),
(4705221, 677517, 41675, '<td valign="top">Uhmm, my first reaction: Ewww! Gross! I didn''t know there were violet worms. The flash is a bit much but an interesting and different close up. You just never know what image will pop up net in these challenges. (Why do I want to wash my hands now?) Lol</td>', 'Uhmm, my first reaction: Ewww! Gross! I didn''t know there were violet worms. The flash is a bit much but an interesting and different close up. You just never know what image will pop up net in these challenges. (Why do I want to wash my hands now?) Lol', '2008-05-15 20:13:44.000000', NULL, 1),
(4705223, 677650, 41675, '<td valign="top">Not a bad image of a sculpture. I like the texture and title is good. Too bad there wasn''t a ffish or something hanging out its mouth to add interest.</td>', 'Not a bad image of a sculpture. I like the texture and title is good. Too bad there wasn''t a ffish or something hanging out its mouth to add interest.', '2008-05-15 20:15:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4705225, 676403, 41675, '<td valign="top">Nice flower macro. Pretty colors and good DOF. This should do well.</td>', 'Nice flower macro. Pretty colors and good DOF. This should do well.', '2008-05-15 20:16:00.000000', NULL, 1),
(4705228, 676421, 41675, '<td valign="top">It''s just me, but I''ve never been a personal fan of photos being entered upside down. I do like the reflection, just not sure why you entered it this way. Title works for the challenge.</td>', 'It''s just me, but I''ve never been a personal fan of photos being entered upside down. I do like the reflection, just not sure why you entered it this way. Title works for the challenge.', '2008-05-15 20:17:11.000000', NULL, 1),
(4705232, 677973, 41675, '<td valign="top">Aside from the noise/grain of the glass, I really like the illumination, the umbrellas and black background. I might have left out the purple in-line border, but still a fun photo to look at.</td>', 'Aside from the noise/grain of the glass, I really like the illumination, the umbrellas and black background. I might have left out the purple in-line border, but still a fun photo to look at.', '2008-05-15 20:18:33.000000', NULL, 1),
(4705233, 677722, 41675, '<td valign="top">Good title. Nice angle, colors and lighting. I like how the tilt of the bike and the ladder direct the eyes to the structure itself. Good luck in the challenge.</td>', 'Good title. Nice angle, colors and lighting. I like how the tilt of the bike and the ladder direct the eyes to the structure itself. Good luck in the challenge.', '2008-05-15 20:19:16.000000', NULL, 1),
(4705234, 677642, 41675, '<td valign="top">Good composition and I like the water droplets on the rose. Good border choice as the I think the black helps "tone down" the red vibrancy of the rose and keeps it from being overpowering. Well done.</td>', 'Good composition and I like the water droplets on the rose. Good border choice as the I think the black helps "tone down" the red vibrancy of the rose and keeps it from being overpowering. Well done.', '2008-05-15 20:20:18.000000', NULL, 1),
(4705236, 677682, 41675, '<td valign="top">DPC is fun - you just never know what image will pop up next. It''s like finding the good prizes in the old cracker jacks boxes. :-) Fun image, well composed and lit. I hope this does really well. One of my top ten.</td>', 'DPC is fun - you just never know what image will pop up next. It''s like finding the good prizes in the old cracker jacks boxes. :-) Fun image, well composed and lit. I hope this does really well. One of my top ten.', '2008-05-15 20:21:32.000000', NULL, 1),
(4705238, 677947, 41675, '<td valign="top">That''s a 50 cent title! Busy image. My eyes aren''t sure where to look or if there''s a main focal point. Good lighting.</td>', 'That''s a 50 cent title! Busy image. My eyes aren''t sure where to look or if there''s a main focal point. Good lighting.', '2008-05-15 20:22:36.000000', NULL, 1),
(4705240, 677579, 41675, '<td valign="top">Shaking my head and laughing at your title. Personally I find insects gross, but as far as an image, yours is a good one. Nice, clean, sharp, good lighting and nice DOF.</td>', 'Shaking my head and laughing at your title. Personally I find insects gross, but as far as an image, yours is a good one. Nice, clean, sharp, good lighting and nice DOF.', '2008-05-15 20:23:32.000000', NULL, 1),
(4705242, 677844, 41675, '<td valign="top">Who-hoo! I can almost hear that splash! Fun capture. Looks like she (or he) has already been in a few times.. For me, I wish the background were a bit more blurred to keep the focus on the dog</td>', 'Who-hoo! I can almost hear that splash! Fun capture. Looks like she (or he) has already been in a few times.. For me, I wish the background were a bit more blurred to keep the focus on the dog', '2008-05-15 20:24:37.000000', NULL, 1),
(4705243, 677669, 41675, '<td valign="top">Good lighting and black &amp; white image. Makes me wonder what they''re looking at. Title works for the challenge.</td>', 'Good lighting and black & white image. Makes me wonder what they''re looking at. Title works for the challenge.', '2008-05-15 20:25:30.000000', NULL, 1),
