(4708537, 677169, 85545, '<td valign="top">I like the photo overall but the way it is composed forces my eyes to the grassy area at the end of the pond.</td>', 'I like the photo overall but the way it is composed forces my eyes to the grassy area at the end of the pond.', '2008-05-17 18:07:15.000000', NULL, 1),
(4708541, 677758, 85545, '<td valign="top">This composition is one that can make you sit and contemplate the many meanings the artist could be portraying in this photo. The lighting and contrast are good. The texture and angle of the letters add depth to the photograph.</td>', 'This composition is one that can make you sit and contemplate the many meanings the artist could be portraying in this photo. The lighting and contrast are good. The texture and angle of the letters add depth to the photograph.', '2008-05-17 18:15:45.000000', NULL, 1),
(4708542, 677670, 85545, '<td valign="top">I really like the concept of your photograph. I can see symbolism that denotes the emotions of people looking at the battleground or even giving their opinions of war.</td>', 'I really like the concept of your photograph. I can see symbolism that denotes the emotions of people looking at the battleground or even giving their opinions of war.', '2008-05-17 18:18:49.000000', NULL, 1),
(4708543, 677892, 85545, '<td valign="top">This photograph has touched me. The title and items bring me to feel a sense of sadness of one who died for his country and will never be forgotten.</td>', 'This photograph has touched me. The title and items bring me to feel a sense of sadness of one who died for his country and will never be forgotten.', '2008-05-17 18:20:13.000000', NULL, 1),
