INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4709143, 677625, 90663, '<td valign="top">Buildings on the right suffer from the "tipping over" look from ground-based perspective, not deducting for it because I don''t think you can straighten those in PP even under advanced rules, overall a nice image</td>', 'Buildings on the right suffer from the "tipping over" look from ground-based perspective, not deducting for it because I don''t think you can straighten those in PP even under advanced rules, overall a nice image', '2008-05-18 03:48:47.000000', NULL, 1),
(4709145, 677824, 90663, '<td valign="top">OK this is the first title in this challenge that made me laugh out loud  ;)    good macro</td>', 'OK this is the first title in this challenge that made me laugh out loud  ;)    good macro', '2008-05-18 03:51:35.000000', NULL, 1),
(4709151, 677703, 90663, '<td valign="top">Working on your own version of the Sistine Chapel?  ;)   Fitting that God is a woman here, any married guy knows that!</td>', 'Working on your own version of the Sistine Chapel?  ;)   Fitting that God is a woman here, any married guy knows that!', '2008-05-18 04:01:09.000000', NULL, 1),
(4709213, 677845, 14867, '<td valign="top">Good composition (even an unusual and original crop for this subject), but seems terribly "over-denoised" with neat image or some software like that, it provides and unnatural plastic appearance.</td>', 'Good composition (even an unusual and original crop for this subject), but seems terribly "over-denoised" with neat image or some software like that, it provides and unnatural plastic appearance.', '2008-05-18 06:14:25.000000', NULL, 1),
(4709214, 677503, 14867, '<td valign="top">Very simple, though elegant, unusual angle, clever use of a dark background to emphasize tteh subject, and good DOF.</td>', 'Very simple, though elegant, unusual angle, clever use of a dark background to emphasize tteh subject, and good DOF.', '2008-05-18 06:19:34.000000', NULL, 1),
(4709216, 677562, 14867, '<td valign="top">Good one, but the righ part of the image is competiting with the subject. If your crop about 1/4 right, you obtain something much better IMO</td>', 'Good one, but the righ part of the image is competiting with the subject. If your crop about 1/4 right, you obtain something much better IMO', '2008-05-18 06:22:09.000000', NULL, 1),
(4709219, 677622, 14867, '<td valign="top">Superb, almost surreal. Seems to be bathed by green, with some contrasting, superbly balanced elements. Classy.</td>', 'Superb, almost surreal. Seems to be bathed by green, with some contrasting, superbly balanced elements. Classy.', '2008-05-18 06:24:21.000000', NULL, 1),
(4709285, 677853, 74703, '<td valign="top">well done catching the sun rays</td>', 'well done catching the sun rays', '2008-05-18 07:43:18.000000', NULL, 1),
(4709446, 677988, 33672, '<td valign="top">One of the best in the comp. 10</td>', 'One of the best in the comp. 10', '2008-05-18 11:55:40.000000', NULL, 1),
(4709595, 677510, 41675, '<td valign="top">I like the soft, warm tones of your image. Reykjavik looks quite beautiful. I also like how the rocks lead the eyes into your image. Well done.</td>', 'I like the soft, warm tones of your image. Reykjavik looks quite beautiful. I also like how the rocks lead the eyes into your image. Well done.', '2008-05-18 13:20:09.000000', NULL, 1),
(4709598, 677983, 41675, '<td valign="top">Your title made me smile and it fits the challenge. For me, the bright white blurred areas of the background are distracting, but I do like the green areas.</td>', 'Your title made me smile and it fits the challenge. For me, the bright white blurred areas of the background are distracting, but I do like the green areas.', '2008-05-18 13:22:06.000000', NULL, 1),
(4709600, 677724, 41675, '<td valign="top">I like how you used b&amp;w for this image. I think color would have made it too busy maybe. Your title fits the challenge and it made me smile.</td>', 'I like how you used b&w for this image. I think color would have made it too busy maybe. Your title fits the challenge and it made me smile.', '2008-05-18 13:24:23.000000', NULL, 1),
(4709602, 676747, 41675, '<td valign="top">I wish there was a bit more light as it looks like quite the interesting structure. It just seems a bit on the dark side for my personal tastes.</td>', 'I wish there was a bit more light as it looks like quite the interesting structure. It just seems a bit on the dark side for my personal tastes.', '2008-05-18 13:25:36.000000', NULL, 1),
(4709604, 677901, 41675, '<td valign="top">Good black &amp; white &amp; photojournalism image. I could easily see this being in a newspaper</td>', 'Good black & white & photojournalism image. I could easily see this being in a newspaper', '2008-05-18 13:27:05.000000', NULL, 1),
(4709607, 677674, 41675, '<td valign="top">Wow! What a fairy-tale like image. Maybe a tad over saturated, but...wow! It''s simply breathtaking. The type of photo you would see in a tourism brochure or magazine.</td>', 'Wow! What a fairy-tale like image. Maybe a tad over saturated, but...wow! It''s simply breathtaking. The type of photo you would see in a tourism brochure or magazine.', '2008-05-18 13:28:07.000000', NULL, 1),
(4709609, 677876, 41675, '<td valign="top">Good post processing. I like the lighting and composition. Your title works and fits the challenge description as well. This should finish in the top ten, I''m thinking. Best of luck.</td>', 'Good post processing. I like the lighting and composition. Your title works and fits the challenge description as well. This should finish in the top ten, I''m thinking. Best of luck.', '2008-05-18 13:30:36.000000', NULL, 1),
(4709612, 677986, 41675, '<td valign="top">For me, your image quality appears grainy and dark. I think if there had been more light or if you had a longer lens to get closer to the deer itself, I would have scored your image higher.</td>', 'For me, your image quality appears grainy and dark. I think if there had been more light or if you had a longer lens to get closer to the deer itself, I would have scored your image higher.', '2008-05-18 13:32:03.000000', NULL, 1),
(4709615, 677777, 41675, '<td valign="top">:-) I like your photo - the street background isn''t distracting, the placement of the two people and especially both of them wearing the red. Very well spotted - you have a good eye.</td>', ':-) I like your photo - the street background isn''t distracting, the placement of the two people and especially both of them wearing the red. Very well spotted - you have a good eye.', '2008-05-18 13:33:50.000000', NULL, 1),
(4709616, 677036, 41675, '<td valign="top">I wish there was another element in your photo to add more interest. It''s not a bad photo, but simply doesn''t keep my attention.</td>', 'I wish there was another element in your photo to add more interest. It''s not a bad photo, but simply doesn''t keep my attention.', '2008-05-18 13:35:19.000000', NULL, 1),
(4709617, 677130, 41675, '<td valign="top">I think had there been an overall sharpened focus with your image, less grain and color flatness, I would have scored it higher. The composition itself is good and it''s interesting to look at. It just seems kind of...flat to me.</td>', 'I think had there been an overall sharpened focus with your image, less grain and color flatness, I would have scored it higher. The composition itself is good and it''s interesting to look at. It just seems kind of...flat to me.', '2008-05-18 13:36:54.000000', NULL, 1),
