(4720453, 677533, 42013, '<td valign="top">Congrats Adam! You really put your unique vision on this classic.</td>', 'Congrats Adam! You really put your unique vision on this classic.', '2008-05-23 19:30:19.000000', NULL, 0),
(4720491, 677868, 25166, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by CarpeLumen:</b></div><hr/><i> not a queen 7 </i></td></tr></table> <br/> <br/>WHO HAS EVER SEEN A ''NON-QUEEN'' BUILD A NEST ON ITS OWN?</td>', 'Originally posted by CarpeLumen: not a queen 7   WHO HAS EVER SEEN A ''NON-QUEEN'' BUILD A NEST ON ITS OWN?', '2008-05-23 20:10:10.000000', NULL, 0),
